import { readFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';
import {
  Assumptions,
  Expr,
  Sym,
  cancel,
  conjugate,
  diff,
  expand,
  factor,
  integrate,
  Integral,
  latex,
  parse,
  roots,
  simplify,
  str,
  together,
  trigsimp,
} from '../src';

// Compatibility tests: expected outputs are generated by SymPy
// (scripts/gen_golden.py tests/golden/cases.json tests/golden/expected.json).

interface Spec {
  symbols: Record<string, Assumptions>;
  cases: { expr: string; ops: string[] }[];
}
interface Expected {
  sympy: string;
  results: { expr: string; out: Record<string, string | string[]> }[];
}

const spec: Spec = JSON.parse(readFileSync(new URL('./golden/cases.json', import.meta.url), 'utf8'));
const expected: Expected = JSON.parse(readFileSync(new URL('./golden/expected.json', import.meta.url), 'utf8'));

const symbols: Record<string, Sym> = Object.fromEntries(
  Object.entries(spec.symbols).map(([name, a]) => [name, new Sym(name, a)]),
);
const x = symbols['x']!;

const OPS: Record<string, (e: Expr) => string | string[]> = {
  str: (e) => str(e),
  latex: (e) => latex(e),
  expand: (e) => str(expand(e)),
  factor: (e) => str(factor(e)),
  simplify: (e) => str(simplify(e)),
  trigsimp: (e) => str(trigsimp(e)),
  together: (e) => str(together(e)),
  cancel: (e) => str(cancel(e)),
  conjugate: (e) => str(conjugate(e)),
  diff_x: (e) => str(diff(e, x)),
  roots_x: (e) => roots(e, x).map(str).sort(),
};

function runOp(op: string, e: Expr): string | string[] {
  if (op.startsWith('integrate:')) {
    const [v, lo, hi] = op.slice('integrate:'.length).split(',');
    const sym = symbols[v!] ?? new Sym(v!);
    if (lo !== undefined && hi !== undefined) {
      return str(integrate(e, sym, [parse(lo, { symbols }), parse(hi, { symbols })]));
    }
    return str(integrate(e, sym));
  }
  if (op === 'latex_integral') {
    return `${latex(new Integral([e, x]))} | ${latex(new Integral([e, x, parse('0'), parse('1')]))}`;
  }
  return OPS[op]!(e);
}

describe(`SymPy ${expected.sympy} compatibility`, () => {
  for (const { expr, out } of expected.results) {
    for (const [op, want] of Object.entries(out)) {
      it(`${op}(${expr})`, () => {
        const e = parse(expr, { symbols });
        expect(runOp(op, e)).toEqual(want);
      });
    }
  }
});
